    "topicTags": [],
    "difficulty": 3,
    "question": "2進数10110を3倍したものはどれか。",
    "choices": {
      "ア": "111010",
      "イ": "111110",
      "ウ": "1000010",
      "エ": "10110000"
    },
    "answer": "ウ",
